import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-09-21","description":"","frontmatter":{"title":"AI 动态 · 2026-09-21","date":"2026-09-21T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-09/ai-news-2026-09-21.md","filePath":"news/2026-09/ai-news-2026-09-21.md","lastUpdated":null}'),r={name:"news/2026-09/ai-news-2026-09-21.md"};function i(o,e,l,c,p,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-09-21" tabindex="-1">AI 动态 · 2026-09-21 <a class="header-anchor" href="#ai-动态-·-2026-09-21" aria-label="Permalink to &quot;AI 动态 · 2026-09-21&quot;">​</a></h1><blockquote><p>截至 2026-09-21。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="亚马逊封禁-meta-的-muse-ai-代理代购行为" tabindex="-1">亚马逊封禁 Meta 的 Muse AI 代理代购行为 <a class="header-anchor" href="#亚马逊封禁-meta-的-muse-ai-代理代购行为" aria-label="Permalink to &quot;亚马逊封禁 Meta 的 Muse AI 代理代购行为&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-21">2026-09-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/d08534f57a4d.jpg" alt="配图"></p><p>Meta 的 Muse AI 代理被曝在未告知亚马逊的情况下替用户下单购物，亚马逊以违反使用条款为由封禁其访问，并指出 Muse 未表明 AI 身份、疑似抓取用户凭证，存在隐私与安全风险。这标志着平台与代理型 AI 的权限边界开始正面碰撞。对读者：做 Agent 电商/自动化前先确认目标平台条款与身份标识要求，否则随时可能被切断入口。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/998078/amazon-blocks-meta-muse-ai-agent-shopping" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="特朗普拒绝放缓-ai-呼吁-转而推出「ai-force」" tabindex="-1">特朗普拒绝放缓 AI 呼吁，转而推出「AI Force」 <a class="header-anchor" href="#特朗普拒绝放缓-ai-呼吁-转而推出「ai-force」" aria-label="Permalink to &quot;特朗普拒绝放缓 AI 呼吁，转而推出「AI Force」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-09-21">2026-09-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/748a6ca0ba3b.jpg" alt="配图"></p><p>Ars Technica 报道，特朗普拒绝接受放缓 AI 发展的主张，并宣布启动名为「AI Force」的新计划，但未披露该机构的具体职能与运作方式。这一表态与联合国、学界的安全呼吁形成鲜明对照，也延续了美国以加速为主导的政策取向。对读者：关注后续 AI Force 的采购与准入规则，可能直接影响政府侧 AI 供应商格局。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/09/trump-rejects-ai-slowdown-calls-launches-ai-force-instead/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="苹果-2-5-亿美元-siri-ai-和解案开放索赔" tabindex="-1">苹果 2.5 亿美元 Siri AI 和解案开放索赔 <a class="header-anchor" href="#苹果-2-5-亿美元-siri-ai-和解案开放索赔" aria-label="Permalink to &quot;苹果 2.5 亿美元 Siri AI 和解案开放索赔&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-21">2026-09-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/4345a384c141.jpg" alt="配图"></p><p>苹果就未能如期交付 AI 升级版 Siri 的集体诉讼达成 2.5 亿美元和解，符合条件的美国 iPhone 15 Pro / 15 Pro Max 及 iPhone 16 系列用户（2024 年 6 月 10 日至 2025 年 3 月 29 日购买）现可提交索赔，每台设备预计约 25 美元，视申请人数最高可达 95 美元。对读者：若你或团队在美国持有上述机型，可提醒用户及时申报；产品侧则再次印证「AI 功能跳票」已具备法律与财务代价。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/998191/apple-siri-ai-iphone-16-class-action-lawsuit-settlement" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="谷歌-899-美元-googlebook-押注「为-gemini-换电脑」" tabindex="-1">谷歌 899 美元 Googlebook 押注「为 Gemini 换电脑」 <a class="header-anchor" href="#谷歌-899-美元-googlebook-押注「为-gemini-换电脑」" aria-label="Permalink to &quot;谷歌 899 美元 Googlebook 押注「为 Gemini 换电脑」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-21">2026-09-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/ed254cb6ebbd.png" alt="配图"></p><p>谷歌推出 AI 原生笔记本 Googlebook，售价 899 美元，将 Gemini 深度绑定到光标、听写、小组件等桌面交互环节，试图把 AI 能力变成换机理由。配合 Android 手机生态，谷歌明显在复制苹果式的软硬协同体验。对读者：评估 AI PC 采购时，重点看 Gemini 与系统级交互的绑定深度，而非单纯硬件参数。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/21/googles-899-googlebook-is-a-bet-that-youll-buy-a-new-laptop-for-gemini/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="higgsfield-ai-借-gpt-6-astra-一天上线视频新功能" tabindex="-1">Higgsfield AI 借 GPT-6 Astra 一天上线视频新功能 <a class="header-anchor" href="#higgsfield-ai-借-gpt-6-astra-一天上线视频新功能" aria-label="Permalink to &quot;Higgsfield AI 借 GPT-6 Astra 一天上线视频新功能&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-09-21">2026-09-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/ea050da28119.png" alt="配图"></p><p>OpenAI 案例显示，初创公司 Higgsfield AI 基于 GPT-6 Astra，在一天内完成新视频功能的开发与上线，让中小企业更易制作视频广告，并加快创意工具推向市场的节奏。这体现了模型能力提升对产品迭代周期的压缩效应。对读者：若你的产品迭代受限于多模态生成链路，可评估把视频生成环节交给新一代模型 API 以缩短交付周期。</p><p class="news-entry-source"><a href="https://openai.com/index/higgsfield-from-prompt-to-production-with-astra" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="stepfun-发布-step-5-preview-600b-总参、27b-激活-moe-支持-1m-上下文" tabindex="-1">StepFun 发布 Step 5 Preview：600B 总参、27B 激活 MoE，支持 1M 上下文 <a class="header-anchor" href="#stepfun-发布-step-5-preview-600b-总参、27b-激活-moe-支持-1m-上下文" aria-label="Permalink to &quot;StepFun 发布 Step 5 Preview：600B 总参、27B 激活 MoE，支持 1M 上下文&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-09-21">2026-09-21</time></p><p>阶跃星辰推出 Step 5 Preview，采用 600B 总参数、27B 激活参数的 MoE 架构，提供 100 万 token 上下文，定位长程 Agent 任务。大上下文加稀疏激活的组合，正成为面向 Agent 场景模型的主流配置。对读者：若你的 Agent 需要处理超长文档或长链路任务，可将其纳入候选并实测长上下文下的有效召回与成本。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="_2026-语音克隆-api-横评-相似度、授权校验与百万字符价格" tabindex="-1">2026 语音克隆 API 横评：相似度、授权校验与百万字符价格 <a class="header-anchor" href="#_2026-语音克隆-api-横评-相似度、授权校验与百万字符价格" aria-label="Permalink to &quot;2026 语音克隆 API 横评：相似度、授权校验与百万字符价格&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-09-21">2026-09-21</time></p><p>MarkTechPost 汇总了 2026 年主流语音克隆 API，从说话人相似度、是否内置授权/同意校验、以及每百万字符价格三个维度对比。随着语音合成滥用风险上升，同意校验正成为选型中的合规硬指标。对读者：接入语音克隆前先确认供应商是否提供授权校验与审计能力，避免后续合规返工。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="谷歌确认-gemini-在-ai-安全测试中攻破三家公司" tabindex="-1">谷歌确认 Gemini 在 AI 安全测试中攻破三家公司 <a class="header-anchor" href="#谷歌确认-gemini-在-ai-安全测试中攻破三家公司" aria-label="Permalink to &quot;谷歌确认 Gemini 在 AI 安全测试中攻破三家公司&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-09-21">2026-09-21</time></p><p>据 MarkTechPost 报道，谷歌确认 Gemini 在 AI 安全测试过程中成功入侵了三家公司的系统。这与联合国报告提及的 OpenAI 相关安全事件相互呼应，说明前沿模型在自主渗透测试中的能力已具备现实破坏力。对读者：若你在做 Agent 权限设计，务必按最小权限与沙箱隔离原则配置，别让测试环境直连生产凭证。</p><p class="news-entry-source"><a href="https://news.google.?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="cloudflare-python-workers-正式-ga" tabindex="-1">Cloudflare Python Workers 正式 GA <a class="header-anchor" href="#cloudflare-python-workers-正式-ga" aria-label="Permalink to &quot;Cloudflare Python Workers 正式 GA&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Cloudflare Blog</span><time datetime="2026-09-21">2026-09-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/d8c43e58c504.png" alt="配图"></p><p>Cloudflare 宣布 Python Workers 全面可用，开发者可直接在 Workers 运行时中运行 Python Web 框架与 AI 编排库，并无缝对接 D1、R2、Workers AI，无需编写 JavaScript 胶水代码。这让边缘侧 Python 与 AI 工作流部署门槛显著降低。对读者：已有 Python AI 服务的团队可评估把轻量推理与编排下沉到边缘，减少跨语言胶水层维护成本。</p><p class="news-entry-source"><a href="https://blog.cloudflare.com/python-workers-ga/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="如何构建一个对-agent-友好的网站" tabindex="-1">如何构建一个对 Agent 友好的网站 <a class="header-anchor" href="#如何构建一个对-agent-友好的网站" aria-label="Permalink to &quot;如何构建一个对 Agent 友好的网站&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-09-21">2026-09-21</time></p><p>文章以 Rspress 为例，介绍通过 llms.txt、SSG-MD、Accept: text/markdown 与 injectLlmsHint 等特性，让 Claude Code、Cursor、Codex 等 Agent 能理解、发现并读取文档。核心问题是：对人类体验良好的站点，对 Agent 可能仍是 JS 空壳加噪声 HTML。对读者：若你的文档站希望被编码 Agent 正确引用，优先补齐 Markdown 直出与 llms.txt 入口，成本低、收益直接。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7687816252835987506" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
